/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (INPUT_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t input_dispatch_on(handle_t ch, const struct input_ops *ops, void *ctx,
                                         const void *req, uint32_t n, void *rep, handle_t *rhs,
                                         uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case INPUT_KEY: {
        const struct input_key_req *idl_q = (const struct input_key_req *)req;
        struct input_key_rep *idl_r = (struct input_key_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->key) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->key(ctx, idl_q->usage, idl_q->state, idl_q->mods, idl_q->codepoint);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case INPUT_MOUSE: {
        const struct input_mouse_req *idl_q = (const struct input_mouse_req *)req;
        struct input_mouse_rep *idl_r = (struct input_mouse_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->mouse) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->mouse(ctx, idl_q->dx, idl_q->dy, idl_q->wheel, idl_q->buttons);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case INPUT_TEXT: {
        const struct input_text_req *idl_q = (const struct input_text_req *)req;
        struct input_text_rep *idl_r = (struct input_text_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->text) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->text(ctx, idl_q->length, idl_q->bytes);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case INPUT_READY: {
        const struct input_ready_req *idl_q = (const struct input_ready_req *)req;
        struct input_ready_rep *idl_r = (struct input_ready_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->ready) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->ready(ctx, idl_q->kind, idl_q->vendor, idl_q->product);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* input_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t input_dispatch(const struct input_ops *ops, void *ctx, const void *req, uint32_t n,
                                      void *rep, handle_t *rhs, uint32_t *rhn)
{
    return input_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request: ERR_INVALID_ARGS if it has less. */
static inline status_t input_take_slot(handle_t ch, const struct idl_slot *slot)
{
    if (slot->qcap < INPUT_REQ_MAX)
        return ERR_INVALID_ARGS;
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by input_take_slot, or found there by a
 * successor), which came on ch: as input_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it can't. */
static inline uint32_t input_run_slot(handle_t ch, const struct idl_slot *slot,
                                      const struct input_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return input_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. */
static inline bool input_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t input_serve_one(handle_t ch, const struct input_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[INPUT_REQ_MAX];
    _Alignas(8) uint8_t idl_r[INPUT_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = input_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t input_serve(handle_t ch, const struct input_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[INPUT_REQ_MAX];
    _Alignas(8) uint8_t idl_r[INPUT_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = input_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
